-- Stage 6: canonical NUMERIC engine, holiday identity, atomic final snapshots.
SET LOCAL ROLE sim_guru_owner;
CREATE TABLE finance.honor_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_start date NOT NULL UNIQUE CHECK(extract(day FROM period_start)=1),state text NOT NULL DEFAULT 'open' CHECK(state IN('open','final')),finalized_at timestamptz,finalized_by uuid REFERENCES app.app_users(id),formula_version text NOT NULL DEFAULT 'honor-v1',policy_version text NOT NULL DEFAULT 'finance-v1',CHECK((state='final')=(finalized_at IS NOT NULL)));
CREATE TABLE finance.holiday_entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_key text NOT NULL UNIQUE,occurrence_id uuid NOT NULL UNIQUE REFERENCES app.activity_occurrences(id),user_id uuid NOT NULL REFERENCES app.app_users(id),date date NOT NULL,jtm numeric(12,4) NOT NULL CHECK(jtm>=0),state text NOT NULL CHECK(state IN('pending','posted','waived')),generation int NOT NULL DEFAULT 0,reason text NOT NULL,version bigint NOT NULL DEFAULT 1);
CREATE INDEX holiday_date ON finance.holiday_entitlements(date,user_id);
CREATE TABLE finance.holiday_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),date date NOT NULL,generation int NOT NULL,state text NOT NULL CHECK(state IN('completed','cancelled')),actor_id uuid NOT NULL REFERENCES app.app_users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(date,generation));
CREATE TABLE finance.holiday_effects(run_id uuid NOT NULL REFERENCES finance.holiday_runs(id),entitlement_id uuid NOT NULL REFERENCES finance.holiday_entitlements(id),ledger_id uuid NOT NULL UNIQUE REFERENCES finance.jtm_ledger(id),PRIMARY KEY(run_id,entitlement_id));
CREATE TABLE finance.transport_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES app.app_users(id),date_start date NOT NULL,date_end date NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 5 AND 500),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK(date_end-date_start BETWEEN 0 AND 365));
CREATE INDEX transport_blocks_window ON finance.transport_blocks(date_start,date_end,user_id) WHERE active;
CREATE TABLE finance.honor_statements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES finance.honor_periods(id),user_id uuid NOT NULL REFERENCES app.app_users(id),trx_id text NOT NULL UNIQUE,snapshot jsonb NOT NULL,total_jtm numeric(16,4) NOT NULL,total_honor numeric(20,0) NOT NULL CHECK(total_honor>=0),checksum text NOT NULL CHECK(length(checksum)=64),UNIQUE(period_id,user_id));
CREATE INDEX statement_owner ON finance.honor_statements(user_id,period_id);
CREATE TABLE finance.honor_statement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),statement_id uuid NOT NULL REFERENCES finance.honor_statements(id),component text NOT NULL,source_ref uuid,ledger_id uuid REFERENCES finance.jtm_ledger(id),snapshot jsonb NOT NULL);
CREATE INDEX statement_lines_parent ON finance.honor_statement_lines(statement_id);
CREATE TABLE finance.document_tokens(token_hash text PRIMARY KEY CHECK(length(token_hash)=64),statement_id uuid NOT NULL REFERENCES finance.honor_statements(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX document_statement ON finance.document_tokens(statement_id);
CREATE TABLE finance.correction_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),statement_id uuid NOT NULL REFERENCES finance.honor_statements(id),requested_by uuid NOT NULL REFERENCES app.app_users(id),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 5 AND 500),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE finance.corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),statement_id uuid NOT NULL REFERENCES finance.honor_statements(id),target_period date NOT NULL CHECK(extract(day FROM target_period)=1),sequence int NOT NULL,baseline_total numeric(20,0) NOT NULL,corrected_total numeric(20,0) NOT NULL CHECK(corrected_total>=0),delta numeric(20,0) NOT NULL,reason text NOT NULL,evidence text NOT NULL,revision jsonb NOT NULL,approved_by uuid NOT NULL REFERENCES app.app_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(statement_id,sequence),CHECK(delta=corrected_total-baseline_total));
CREATE INDEX correction_target ON finance.corrections(target_period,statement_id);
CREATE TABLE finance.notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key text NOT NULL UNIQUE,recipient_id uuid NOT NULL REFERENCES app.app_users(id),statement_id uuid NOT NULL REFERENCES finance.honor_statements(id),kind text NOT NULL CHECK(kind IN('honor_final','honor_correction')),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','sent','failed')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE ops.finance_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app.app_users(id),request jsonb NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes',consumed_at timestamptz);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['finance.honor_periods','finance.holiday_entitlements','finance.holiday_runs','finance.holiday_effects','finance.transport_blocks','finance.honor_statements','finance.honor_statement_lines','finance.document_tokens','finance.correction_requests','finance.corrections','finance.notification_outbox','ops.finance_previews'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY owner_internal ON %s TO sim_guru_owner USING(true) WITH CHECK(true)',t);EXECUTE format('REVOKE ALL ON %s FROM PUBLIC,sim_guru_business,sim_guru_auth,sim_guru_worker',t);END LOOP;END $$;
CREATE FUNCTION finance.digest(p_value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(p_value,'UTF8')),'hex') $$;
CREATE FUNCTION finance.month_start(p_period text) RETURNS date LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ BEGIN IF p_period IS NULL OR p_period!~'^(20[0-9]{2}|21[0-9]{2})-(0[1-9]|1[0-2])$' THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;RETURN(p_period||'-01')::date;END $$;
CREATE FUNCTION finance.today() RETURNS date LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT (transaction_timestamp() AT TIME ZONE 'Asia/Jakarta')::date $$;
CREATE FUNCTION finance.transport_round(p_raw numeric) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT trunc(p_raw/1000)*1000+CASE WHEN mod(p_raw,1000)<333.34 THEN 0 WHEN mod(p_raw,1000)<666.67 THEN 500 ELSE 1000 END $$;
CREATE OR REPLACE FUNCTION app.schedule_dependencies() RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass('finance.honor_periods') AND attname='period_start' AND NOT attisdropped) THEN RAISE EXCEPTION 'CONTEXT_DEPENDENCY_UNAVAILABLE' USING ERRCODE='55000';END IF;END $$;
-- Final month lock is shared with all existing journal/attendance/adjustment commands.
CREATE FUNCTION finance.final_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE lo date;hi date;d date;BEGIN
 PERFORM pg_advisory_xact_lock(734190,1);
 IF TG_TABLE_NAME IN('academic_calendar','day_context_overrides') THEN lo:=NEW.date;hi:=NEW.date;
 ELSIF TG_TABLE_NAME='teaching_schedules' OR TG_TABLE_NAME='duty_schedules' THEN lo:=NEW.valid_from;hi:=NEW.valid_to;IF TG_OP='UPDATE' THEN
 IF (to_jsonb(NEW)-ARRAY['valid_to','state','version','archived_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['valid_to','state','version','archived_at']) AND NEW.valid_to<>OLD.valid_to AND NEW.state<>'archived' THEN lo:=least(NEW.valid_to,OLD.valid_to)+1;hi:=greatest(NEW.valid_to,OLD.valid_to);
 ELSE lo:=least(lo,OLD.valid_from);hi:=greatest(hi,OLD.valid_to);END IF;END IF;
 ELSIF TG_TABLE_NAME='jtm_ledger' THEN lo:=NEW.date;hi:=NEW.date;
 ELSE lo:=NEW.date_start;hi:=NEW.date_end;END IF;
 FOR d IN SELECT period_start FROM finance.period_guards WHERE finalized_at IS NOT NULL AND period_start<=hi AND(period_start+interval '1 month')::date>lo ORDER BY period_start LOOP RAISE EXCEPTION 'FINAL_PERIOD' USING ERRCODE='42501';END LOOP;RETURN NEW;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['app.academic_calendar','app.day_context_overrides','app.teaching_schedules','app.duty_schedules','app.rate_versions','app.allowances','finance.transport_blocks','finance.jtm_ledger'] LOOP EXECUTE format('CREATE TRIGGER finance_final_guard BEFORE INSERT OR UPDATE ON %s FOR EACH ROW EXECUTE FUNCTION finance.final_guard()',t);END LOOP;END $$;
ALTER TABLE finance.jtm_ledger ADD COLUMN holiday_entitlement_id uuid REFERENCES finance.holiday_entitlements(id);
ALTER TABLE finance.jtm_ledger DROP CONSTRAINT ledger_source_kind;
ALTER TABLE finance.jtm_ledger ADD CONSTRAINT ledger_source_kind CHECK(source_kind IN('KBM','PIKET','UPACARA','EXAM_SUPERVISOR','EXAM_COMMITTEE','EVENT','PARTIAL_SUB_KBM','PARTIAL_SUB_PIKET','PARTIAL_SUB_EXAM','HOLIDAY_BONUS','REVERSAL'));
-- The stage4 shape constraint was expanded by stage5 dynamically. Allow typed holiday entries.
DO $$ DECLARE r record;BEGIN FOR r IN SELECT conname,pg_get_constraintdef(oid) def FROM pg_constraint WHERE conrelid='finance.jtm_ledger'::regclass AND contype='c' AND conname<>'ledger_source_kind' LOOP IF r.def LIKE '%source_kind%' THEN EXECUTE format('ALTER TABLE finance.jtm_ledger DROP CONSTRAINT %I',r.conname);EXECUTE format('ALTER TABLE finance.jtm_ledger ADD CONSTRAINT %I CHECK ((source_kind=''HOLIDAY_BONUS'' AND holiday_entitlement_id IS NOT NULL AND jtm>=0 AND reverses_id IS NULL) OR (%s))',r.conname,substring(r.def FROM 8 FOR length(r.def)-8));END IF;END LOOP;END $$;
CREATE UNIQUE INDEX holiday_ledger_generation ON finance.jtm_ledger(holiday_entitlement_id,revision) WHERE source_kind='HOLIDAY_BONUS';
ALTER FUNCTION finance.ledger_integrity() RENAME TO stage5_ledger_integrity;
-- A trigger function cannot be delegated directly; preserve the exact previous body behind a branch.
DO $$ DECLARE b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid='finance.stage5_ledger_integrity()'::regprocedure;EXECUTE 'CREATE OR REPLACE FUNCTION finance.ledger_integrity() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS '||quote_literal('DECLARE h finance.holiday_entitlements%ROWTYPE; BEGIN IF TG_OP=''INSERT'' AND NEW.source_kind=''HOLIDAY_BONUS'' THEN SELECT * INTO h FROM finance.holiday_entitlements WHERE id=NEW.holiday_entitlement_id; IF h.id IS NULL OR h.state<>''posted'' OR (NEW.occurrence_id,NEW.user_id,NEW.date,NEW.jtm,NEW.revision) IS DISTINCT FROM (h.occurrence_id,h.user_id,h.date,h.jtm,h.generation::bigint) OR NEW.journal_id IS NOT NULL OR NEW.assignment_id IS NOT NULL OR NEW.allocation_id IS NOT NULL THEN RAISE EXCEPTION ''FINANCE_INVALID'' USING ERRCODE=''22023'';END IF;RETURN NEW;END IF; IF TG_OP=''INSERT'' AND NEW.holiday_entitlement_id IS NOT NULL AND NEW.source_kind<>''REVERSAL'' THEN RAISE EXCEPTION ''FINANCE_INVALID'' USING ERRCODE=''22023'';END IF; '||b||'; END');END $$;
-- Trigger OID follows the renamed routine, so explicitly replace it with the expanded validator.
DROP TRIGGER ledger_integrity ON finance.jtm_ledger;
CREATE TRIGGER ledger_integrity BEFORE INSERT OR UPDATE OR DELETE ON finance.jtm_ledger FOR EACH ROW EXECUTE FUNCTION finance.ledger_integrity();
CREATE FUNCTION finance.holiday_candidates(p_month date) RETURNS TABLE(source_key text,kind text,schedule_id uuid,duty_id uuid,date date,user_id uuid,academic_period_id uuid,class_id uuid,subject_id uuid,time_start time,time_end time,jtm numeric,snapshot jsonb) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH days AS(SELECT c.date,coalesce(o.academic_period_id,a.id) academic_id FROM app.academic_calendar c JOIN app.academic_periods a ON c.date BETWEEN a.date_start AND a.date_end LEFT JOIN app.day_context_overrides o ON o.date=c.date AND o.deleted_at IS NULL WHERE c.is_holiday AND c.deleted_at IS NULL AND c.date>=p_month AND c.date<(p_month+interval '1 month')::date AND a.archived_at IS NULL AND(a.is_active OR EXISTS(SELECT 1 FROM app.teaching_schedules s WHERE s.academic_period_id=a.id AND c.date BETWEEN s.valid_from AND s.valid_to)) AND(o.id IS NULL OR o.academic_period_id=a.id)),
 candidates AS(SELECT 'KBM:'||s.id||':'||d.date source_key,'KBM' kind,s.id schedule_id,null::uuid duty_id,d.date,s.user_id,s.academic_period_id,s.class_id,s.subject_id,s.time_start,s.time_end,s.scheduled_jtm jtm,s.snapshot FROM days d JOIN app.teaching_schedules s ON s.academic_period_id=d.academic_id AND d.date BETWEEN s.valid_from AND s.valid_to AND extract(dow FROM d.date)=s.day_index AND s.state<>'archived'
 UNION ALL SELECT s.kind||':'||s.id||':'||d.date,s.kind,null::uuid,s.id,d.date,s.user_id,s.academic_period_id,null::uuid,null::uuid,s.time_start,s.time_end,CASE s.kind WHEN 'PIKET' THEN 4 ELSE 5 END,jsonb_build_object('kind',s.kind) FROM days d JOIN app.duty_schedules s ON s.academic_period_id=d.academic_id AND s.active AND d.date BETWEEN s.valid_from AND s.valid_to AND extract(dow FROM d.date)=s.day_index AND(s.kind='PIKET' OR extract(dow FROM d.date)=1))
 SELECT DISTINCT c.* FROM candidates c JOIN app.app_users u ON u.id=c.user_id WHERE u.role='guru' AND (u.status='active' OR EXISTS(SELECT 1 FROM finance.holiday_entitlements h WHERE h.source_key=c.source_key)) AND NOT EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.teaching_journals j ON j.occurrence_id=o.id AND j.deleted_at IS NULL WHERE o.date=c.date AND(o.schedule_id=c.schedule_id OR o.duty_schedule_id=c.duty_id)) AND NOT EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN finance.jtm_ledger l ON l.occurrence_id=o.id WHERE o.date=c.date AND(o.schedule_id=c.schedule_id OR o.duty_schedule_id=c.duty_id) AND l.source_kind NOT IN('HOLIDAY_BONUS','REVERSAL') AND NOT EXISTS(SELECT 1 FROM finance.jtm_ledger r WHERE r.reverses_id=l.id)) $$;
CREATE FUNCTION finance.holiday_command(p_actor uuid,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE d date:=(p_data->>'date')::date;op text:=p_data->>'operation';c record;h finance.holiday_entitlements%ROWTYPE;r finance.holiday_runs%ROWTYPE;occ uuid;entry uuid;n int:=0;g int;v_reason text:=p_data->>'reason';BEGIN
 IF op NOT IN('generate','cancel','waive') OR d IS NULL OR d>finance.today() OR length(btrim(coalesce(v_reason,''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;PERFORM finance.guard_open(d);
 IF op='generate' AND d=finance.today() AND(clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::time<time '16:00' THEN RAISE EXCEPTION 'HOLIDAY_NOT_DUE' USING ERRCODE='42501';END IF;
 IF op='cancel' THEN SELECT * INTO r FROM finance.holiday_runs WHERE id=(p_data->>'runId')::uuid AND date=d FOR UPDATE;IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF r.state='cancelled' THEN RETURN jsonb_build_object('count',0,'runId',r.id,'state','cancelled');END IF;
 INSERT INTO finance.jtm_ledger(source_kind,occurrence_id,user_id,date,jtm,revision,reverses_id,holiday_entitlement_id) SELECT 'REVERSAL',l.occurrence_id,l.user_id,l.date,-l.jtm,l.revision,l.id,l.holiday_entitlement_id FROM finance.holiday_effects e JOIN finance.jtm_ledger l ON l.id=e.ledger_id WHERE e.run_id=r.id AND NOT EXISTS(SELECT 1 FROM finance.jtm_ledger q WHERE q.reverses_id=l.id);GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE finance.holiday_entitlements SET state='pending',version=version+1,reason=v_reason WHERE id IN(SELECT entitlement_id FROM finance.holiday_effects WHERE run_id=r.id);UPDATE finance.holiday_runs SET state='cancelled' WHERE id=r.id;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM app.academic_calendar WHERE date=d AND is_holiday AND deleted_at IS NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 SELECT coalesce(max(generation),0)+1 INTO g FROM finance.holiday_runs WHERE date=d;
 IF op='generate' AND NOT EXISTS(SELECT 1 FROM finance.holiday_candidates(date_trunc('month',d)::date) cand LEFT JOIN finance.holiday_entitlements ent ON ent.source_key=cand.source_key WHERE cand.date=d AND coalesce(ent.state,'pending') NOT IN('posted','waived')) THEN RETURN jsonb_build_object('count',0,'runId',(SELECT id FROM finance.holiday_runs WHERE date=d ORDER BY generation DESC LIMIT 1),'operation',op);END IF; IF op='generate' THEN INSERT INTO finance.holiday_runs(date,generation,state,actor_id,reason) VALUES(d,g,'completed',p_actor,v_reason) RETURNING * INTO r;END IF;
 FOR c IN SELECT * FROM finance.holiday_candidates(date_trunc('month',d)::date) WHERE date=d ORDER BY source_key LOOP
 SELECT * INTO h FROM finance.holiday_entitlements WHERE source_key=c.source_key;
 IF h.state IN('posted','waived') THEN CONTINUE;END IF;
 IF h.id IS NULL THEN
 INSERT INTO app.activity_occurrences(kind,schedule_id,duty_schedule_id,date,academic_period_id,class_id,subject_id,time_start,time_end,scheduled_jtm,expected_students,snapshot) VALUES(c.kind,c.schedule_id,c.duty_id,c.date,c.academic_period_id,c.class_id,c.subject_id,c.time_start,c.time_end,c.jtm,coalesce((SELECT expected_students FROM app.classes WHERE id=c.class_id),0),c.snapshot||jsonb_build_object('holiday',true,'material','Auto-generated: Libur Bonus')) ON CONFLICT DO NOTHING;
 SELECT id INTO occ FROM app.activity_occurrences WHERE date=d AND(schedule_id=c.schedule_id OR duty_schedule_id=c.duty_id);
 INSERT INTO app.activity_assignments(occurrence_id,original_user_id,effective_user_id,effective_name) SELECT occ,c.user_id,c.user_id,full_name FROM app.app_users WHERE id=c.user_id ON CONFLICT DO NOTHING;
 INSERT INTO finance.holiday_entitlements(source_key,occurrence_id,user_id,date,jtm,state,reason) VALUES(c.source_key,occ,c.user_id,d,c.jtm,'pending',v_reason) RETURNING * INTO h;
 END IF;
 IF op='waive' THEN UPDATE finance.holiday_entitlements SET state='waived',reason=v_reason,version=version+1 WHERE id=h.id;
 ELSE UPDATE finance.holiday_entitlements SET state='posted',generation=generation+1,version=version+1,reason=v_reason WHERE id=h.id RETURNING * INTO h;
 INSERT INTO finance.jtm_ledger(source_kind,occurrence_id,user_id,date,jtm,revision,holiday_entitlement_id) VALUES('HOLIDAY_BONUS',h.occurrence_id,h.user_id,h.date,h.jtm,h.generation,h.id) RETURNING id INTO entry;INSERT INTO finance.holiday_effects(run_id,entitlement_id,ledger_id) VALUES(r.id,h.id,entry);END IF;n:=n+1;END LOOP;
 END IF;PERFORM app.activity_audit('holiday',coalesce(r.id,p_actor),v_reason,null,jsonb_build_object('operation',op,'count',n));RETURN jsonb_build_object('count',n,'runId',r.id,'operation',op);END $$;
CREATE FUNCTION finance.transport_lines(p_user uuid,p_month date,p_cutoff date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH rows AS(SELECT d.*,u.km_distance,r.id rate_id,coalesce(CASE WHEN r.enabled THEN r.amount ELSE 0 END,0) rate,coalesce((app.attendance_dto(d.id)->>'effectiveMinutes')::numeric,0) effective_minutes,EXISTS(SELECT 1 FROM finance.transport_blocks b WHERE b.active AND(b.user_id IS NULL OR b.user_id=d.user_id) AND d.date BETWEEN b.date_start AND b.date_end) blocked FROM app.daily_attendance d JOIN app.app_users u ON u.id=d.user_id LEFT JOIN app.rate_versions r ON r.kind='transport' AND r.archived_at IS NULL AND d.date BETWEEN r.date_start AND r.date_end WHERE d.user_id=p_user AND d.date>=p_month AND d.date<(p_month+interval '1 month')::date AND d.date<=p_cutoff),
 ratios AS(SELECT *,CASE WHEN sched_time_in IS NOT NULL AND sched_time_out>sched_time_in THEN extract(epoch FROM(sched_time_out-sched_time_in))/60 WHEN extra_attendee AND effective_minutes>0 THEN effective_minutes ELSE 0 END scheduled_minutes FROM rows), amounts AS(SELECT *,CASE WHEN blocked OR scheduled_minutes<=0 OR effective_minutes<=0 OR km_distance<=0 THEN 0 ELSE km_distance*rate*least(1,div(effective_minutes*'1e40'::numeric,scheduled_minutes)/'1e40'::numeric) END raw_amount FROM ratios)
 SELECT coalesce(jsonb_agg(jsonb_build_object('component','TRANSPORT','sourceRef',id,'date',date,'scheduledIn',sched_time_in,'scheduledOut',sched_time_out,'actualIn',actual_time_in,'actualOut',actual_time_out,'extraAttendee',extra_attendee,'version',version::text,'effectiveMinutes',effective_minutes::text,'scheduledMinutes',scheduled_minutes::text,'distance',km_distance::text,'rate',rate::text,'rateId',rate_id,'blocked',blocked,'ratio',CASE WHEN scheduled_minutes>0 THEN round(least(1,effective_minutes/scheduled_minutes),3)::text ELSE '0' END,'raw',raw_amount::text) ORDER BY date,id),'[]') FROM amounts $$;
CREATE FUNCTION finance.calculate(p_user uuid,p_month date,p_mode text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE last_day date:=(p_month+interval '1 month - 1 day')::date;cutoff date:=least(finance.today(),last_day);rate app.rate_versions%ROWTYPE;recipient jsonb;school jsonb;lines jsonb;trans jsonb;allows jsonb;corr jsonb;pending jsonb;total_jtm numeric;teaching numeric;transport_raw numeric;allowance_total numeric;correction_total numeric;BEGIN
 IF p_mode NOT IN('realized','projection') THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 SELECT * INTO rate FROM app.rate_versions WHERE kind='jtm' AND archived_at IS NULL AND last_day BETWEEN date_start AND date_end;
 SELECT jsonb_build_object('id',id,'name',full_name,'nip',nip,'username',username,'distance',km_distance::text) INTO recipient FROM app.app_users WHERE id=p_user;
 SELECT jsonb_build_object('name',s.name,'address',s.address,'npsn',s.npsn,'headmaster',u.full_name,'headmasterNip',u.nip,'version',s.version::text) INTO school FROM app.school_profiles s LEFT JOIN app.app_users u ON u.id=s.headmaster_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('component',l.source_kind,'sourceRef',coalesce(l.holiday_entitlement_id,l.allocation_id,l.assignment_id,l.journal_id),'ledgerId',l.id,'occurrenceId',l.occurrence_id,'date',l.date,'jtm',l.jtm::text,'revision',l.revision::text,'reversesId',l.reverses_id,'sourceSnapshot',o.snapshot) ORDER BY l.date,l.id),'[]'),coalesce(sum(l.jtm),0) INTO lines,total_jtm FROM finance.jtm_ledger l JOIN app.activity_occurrences o ON o.id=l.occurrence_id WHERE l.user_id=p_user AND l.date>=p_month AND l.date<=cutoff;
 SELECT coalesce(jsonb_agg(jsonb_build_object('component','HOLIDAY_PENDING','sourceRef',h.id,'sourceKey',c.source_key,'date',c.date,'jtm',c.jtm::text,'state',coalesce(h.state,'projected')) ORDER BY c.date,c.source_key),'[]') INTO pending FROM finance.holiday_candidates(p_month) c LEFT JOIN finance.holiday_entitlements h ON h.source_key=c.source_key WHERE c.user_id=p_user AND coalesce(h.state,'pending') NOT IN('posted','waived') AND(p_mode='projection' OR c.date<=cutoff);
 IF p_mode='projection' THEN SELECT total_jtm+coalesce(sum((x->>'jtm')::numeric),0) INTO total_jtm FROM jsonb_array_elements(pending) x;lines:=lines||pending;END IF;
 trans:=finance.transport_lines(p_user,p_month,cutoff);SELECT coalesce(sum((x->>'raw')::numeric),0) INTO transport_raw FROM jsonb_array_elements(trans) x;
 SELECT coalesce(jsonb_agg(jsonb_build_object('component','ALLOWANCE','sourceRef',id,'name',duty_name,'amount',amount::text,'dateStart',date_start,'dateEnd',date_end,'version',version::text) ORDER BY id),'[]'),coalesce(sum(amount),0) INTO allows,allowance_total FROM app.allowances WHERE user_id=p_user AND archived_at IS NULL AND last_day BETWEEN date_start AND date_end;
 SELECT coalesce(jsonb_agg(jsonb_build_object('component','CORRECTION','sourceRef',c.id,'sourceStatementId',c.statement_id,'delta',c.delta::text,'reason',c.reason,'sequence',c.sequence) ORDER BY c.id),'[]'),coalesce(sum(c.delta),0) INTO corr,correction_total FROM finance.corrections c JOIN finance.honor_statements s ON s.id=c.statement_id WHERE s.user_id=p_user AND c.target_period=p_month;
 teaching:=total_jtm*coalesce(CASE WHEN rate.enabled THEN rate.amount ELSE 0 END,0);
 RETURN jsonb_build_object('schemaVersion',1,'formulaVersion','honor-v1','policyVersion','finance-v1','period',to_char(p_month,'YYYY-MM'),'mode',p_mode,'cutoff',cutoff,'recipient',recipient,'school',school,'ratePolicy','month_end','allowancePolicy','month_end_no_proration','rateId',rate.id,'rate',coalesce(CASE WHEN rate.enabled THEN rate.amount ELSE 0 END,0)::text,'rateMissing',rate.id IS NULL,'totalJtm',total_jtm::text,'teachingRaw',teaching::text,'teachingSettled',round(teaching)::text,'allowances',allowance_total::text,'transportRaw',transport_raw::text,'transportSettled',finance.transport_round(transport_raw)::text,'corrections',correction_total::text,'total',(round(teaching)+allowance_total+finance.transport_round(transport_raw)+correction_total)::text,'lines',lines||allows||trans||corr,'pendingHolidays',pending);
END $$;
CREATE FUNCTION finance.bundle(p_month date,p_mode text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE result jsonb:='[]';issues jsonb:='[]';u record;s jsonb;last_day date:=(p_month+interval '1 month - 1 day')::date;BEGIN
 FOR u IN SELECT id FROM app.app_users WHERE role='guru' AND status='active' UNION SELECT user_id FROM finance.jtm_ledger WHERE date>=p_month AND date<=last_day UNION SELECT user_id FROM app.daily_attendance WHERE date>=p_month AND date<=last_day AND actual_time_in IS NOT NULL AND actual_time_out IS NOT NULL UNION SELECT user_id FROM app.allowances WHERE archived_at IS NULL AND last_day BETWEEN date_start AND date_end UNION SELECT s.user_id FROM finance.corrections c JOIN finance.honor_statements s ON s.id=c.statement_id WHERE c.target_period=p_month ORDER BY id LOOP s:=finance.calculate(u.id,p_month,p_mode);result:=result||jsonb_build_array(s);IF(s->>'total')::numeric<0 THEN issues:=issues||jsonb_build_array('NEGATIVE_PAYABLE:'||u.id);END IF;IF(s->>'rateMissing')::boolean THEN issues:=issues||'"RATE_MISSING"'::jsonb;END IF;END LOOP;
 IF last_day>=finance.today() THEN issues:=issues||'"PERIOD_NOT_ENDED"'::jsonb;END IF;
 IF NOT EXISTS(SELECT 1 FROM app.school_profiles sp JOIN app.app_users signer ON signer.id=sp.headmaster_id) THEN issues:=issues||'"SCHOOL_SIGNATORY_MISSING"'::jsonb;END IF;
 IF EXISTS(SELECT 1 FROM finance.holiday_candidates(p_month) c LEFT JOIN finance.holiday_entitlements h ON h.source_key=c.source_key WHERE coalesce(h.state,'pending') NOT IN('posted','waived')) OR EXISTS(SELECT 1 FROM finance.holiday_entitlements WHERE date>=p_month AND date<=last_day AND state='pending') THEN issues:=issues||'"HOLIDAY_PENDING"'::jsonb;END IF;
 IF EXISTS(SELECT 1 FROM finance.holiday_entitlements h WHERE h.date>=p_month AND h.date<=last_day AND h.state='posted' AND(NOT EXISTS(SELECT 1 FROM finance.holiday_candidates(p_month) c WHERE c.source_key=h.source_key) OR NOT EXISTS(SELECT 1 FROM finance.jtm_ledger l WHERE l.holiday_entitlement_id=h.id AND l.source_kind='HOLIDAY_BONUS' AND NOT EXISTS(SELECT 1 FROM finance.jtm_ledger r WHERE r.reverses_id=l.id)))) THEN issues:=issues||'"HOLIDAY_INCONSISTENT"'::jsonb;END IF;
 IF EXISTS(SELECT 1 FROM finance.jtm_ledger WHERE date>=p_month AND date<=last_day GROUP BY occurrence_id,user_id HAVING sum(jtm)<0) THEN issues:=issues||'"LEDGER_INCONSISTENT"'::jsonb;END IF;
 RETURN jsonb_build_object('period',to_char(p_month,'YYYY-MM'),'mode',p_mode,'statements',result,'issues',issues,'beneficiaries',jsonb_array_length(result));END $$;
CREATE FUNCTION finance.correction_basis(p_data jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE s finance.honor_statements%ROWTYPE;c finance.corrections%ROWTYPE;target date:=finance.month_start(p_data->>'targetPeriod');j numeric;allowance numeric;transport numeric;corrected numeric;BEGIN
 SELECT * INTO s FROM finance.honor_statements WHERE id=(p_data->>'statementId')::uuid;IF s.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;
 IF target<=(SELECT period_start FROM finance.honor_periods WHERE id=s.period_id) THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 IF coalesce(p_data->>'correctedJtm','')!~'^(0|[1-9][0-9]{0,7})(\.[0-9]{1,4})?$' OR coalesce(p_data->>'correctedAllowances','')!~'^(0|[1-9][0-9]{0,14})$' OR coalesce(p_data->>'correctedTransportRaw','')!~'^(0|[1-9][0-9]{0,14})(\.[0-9]{1,100})?$' OR length(btrim(coalesce(p_data->>'reason',''))) NOT BETWEEN 5 AND 500 OR length(btrim(coalesce(p_data->>'evidence',''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 SELECT * INTO c FROM finance.corrections WHERE statement_id=s.id ORDER BY sequence DESC LIMIT 1;
 j:=(p_data->>'correctedJtm')::numeric;allowance:=(p_data->>'correctedAllowances')::numeric;transport:=(p_data->>'correctedTransportRaw')::numeric;corrected:=round(j*(s.snapshot->>'rate')::numeric)+allowance+finance.transport_round(transport)+(s.snapshot->>'corrections')::numeric;
 RETURN jsonb_build_object('sourceStatementId',s.id,'sourceChecksum',s.checksum,'targetPeriod',to_char(target,'YYYY-MM'),'sequence',coalesce(c.sequence,0)+1,'baseline',coalesce(c.corrected_total,s.total_honor)::text,'correctedTotal',corrected::text,'delta',(corrected-coalesce(c.corrected_total,s.total_honor))::text,'recipientId',s.user_id,'revision',jsonb_build_object('totalJtm',j::text,'rate',s.snapshot->>'rate','allowances',allowance::text,'transportRaw',transport::text,'evidence',p_data->>'evidence','reason',p_data->>'reason'));
END $$;
CREATE FUNCTION app.finance_read(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;kind text:=p_data->>'kind';m date;result jsonb;own boolean;sz int;pg int;BEGIN actor:=app.activity_guard(p_session,false);own:=NOT app.actor_is_admin();
 IF kind IN('estimate','recap') THEN m:=finance.month_start(p_data->>'period');IF kind='recap' THEN PERFORM auth_private.require_admin();END IF;
 IF EXISTS(SELECT 1 FROM finance.honor_periods WHERE period_start=m AND state='final') THEN SELECT jsonb_build_object('period',p_data->>'period','mode','final','issues','[]'::jsonb,'statements',coalesce(jsonb_agg(s.snapshot ORDER BY s.user_id),'[]')) INTO result FROM finance.honor_statements s JOIN finance.honor_periods p ON p.id=s.period_id WHERE p.period_start=m AND(NOT own OR s.user_id=actor);RETURN result;END IF;
 IF own THEN RETURN jsonb_build_object('period',p_data->>'period','mode',p_data->>'mode','statements',jsonb_build_array(finance.calculate(actor,m,p_data->>'mode')),'issues','[]'::jsonb);END IF;RETURN finance.bundle(m,p_data->>'mode');
 ELSIF kind='statement' THEN SELECT jsonb_build_object('id',s.id,'trxId',s.trx_id,'checksum',s.checksum,'snapshot',s.snapshot,'corrected',EXISTS(SELECT 1 FROM finance.corrections WHERE statement_id=s.id)) INTO result FROM finance.honor_statements s WHERE id=(p_data->>'id')::uuid AND(NOT own OR user_id=actor);IF result IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;RETURN result;
 ELSIF kind='history' THEN sz:=coalesce((p_data->>'pageSize')::int,20);pg:=coalesce((p_data->>'page')::int,1);IF sz NOT BETWEEN 1 AND 100 OR pg NOT BETWEEN 1 AND 100000 OR length(coalesce(p_data->>'q',''))>100 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 WITH f AS(SELECT s.id,s.trx_id,s.snapshot->'recipient'->>'name' name,s.total_jtm::text jtm,s.total_honor::text total,to_char(p.period_start,'YYYY-MM') period FROM finance.honor_statements s JOIN finance.honor_periods p ON p.id=s.period_id WHERE(NOT own OR s.user_id=actor) AND(coalesce(p_data->>'period','')='' OR to_char(p.period_start,'YYYY-MM')=p_data->>'period') AND(coalesce(p_data->>'q','')='' OR position(lower(p_data->>'q') in lower(concat_ws(' ',s.trx_id,s.snapshot->'recipient'->>'name')))>0)),paged AS(SELECT * FROM f ORDER BY period DESC,id LIMIT sz OFFSET(pg-1)*sz) SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(paged) ORDER BY period DESC,id) FROM paged),'[]'),'total',(SELECT count(*) FROM f),'page',pg,'pageSize',sz) INTO result;RETURN result;
 ELSIF kind='operations' THEN PERFORM auth_private.require_admin();m:=finance.month_start(p_data->>'period');RETURN jsonb_build_object('holidays',coalesce((SELECT jsonb_agg(jsonb_build_object('sourceKey',c.source_key,'kind',c.kind,'date',c.date,'userId',c.user_id,'name',u.full_name,'jtm',c.jtm::text,'state',coalesce(h.state,'projected')) ORDER BY c.date,c.source_key) FROM finance.holiday_candidates(m) c JOIN app.app_users u ON u.id=c.user_id LEFT JOIN finance.holiday_entitlements h ON h.source_key=c.source_key),'[]'),'runs',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY created_at DESC) FROM finance.holiday_runs r WHERE date>=m AND date<(m+interval '1 month')::date),'[]'),'blocks',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY date_start,id) FROM finance.transport_blocks b WHERE date_start<(m+interval '1 month')::date AND date_end>=m),'[]'),'requests',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY created_at DESC) FROM finance.correction_requests r),'[]'),'notificationQueue','worker_stage_7');
 ELSE RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;END $$;
CREATE FUNCTION finance.waive_impact(p_data jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('operation','waive','count',count(*),'jtm',coalesce(sum(c.jtm),0)::text,'sources',coalesce(jsonb_agg(jsonb_build_object('sourceKey',c.source_key,'userId',c.user_id,'jtm',c.jtm::text,'version',h.version) ORDER BY c.source_key),'[]')) FROM finance.holiday_candidates(date_trunc('month',(p_data->>'date')::date)::date) c LEFT JOIN finance.holiday_entitlements h ON h.source_key=c.source_key WHERE c.date=(p_data->>'date')::date AND coalesce(h.state,'pending') NOT IN('posted','waived') $$;
CREATE FUNCTION app.finance_command(p_session text,p_operation text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;v ops.finance_previews%ROWTYPE;res jsonb;m date;sid uuid;s jsonb;l jsonb;pid uuid;checksum text;tok text;d jsonb;rid uuid;reason text;BEGIN
 actor:=app.activity_guard(p_session,true);reason:=p_data->>'reason';
 IF p_operation='request' THEN SELECT id INTO sid FROM finance.honor_statements WHERE id=(p_data->>'statementId')::uuid AND(user_id=actor OR app.actor_is_admin());IF sid IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF length(btrim(coalesce(reason,''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;INSERT INTO finance.correction_requests(statement_id,requested_by,reason) VALUES(sid,actor,reason) RETURNING id INTO rid;PERFORM app.activity_audit('correction-request',rid,reason,null,null);RETURN jsonb_build_object('id',rid);
 ELSIF p_operation='token' THEN SELECT id INTO sid FROM finance.honor_statements WHERE id=(p_data->>'statementId')::uuid AND(user_id=actor OR app.actor_is_admin());IF sid IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;tok:=replace(gen_random_uuid()::text||gen_random_uuid()::text||gen_random_uuid()::text,'-','');INSERT INTO finance.document_tokens(token_hash,statement_id) VALUES(finance.digest(tok),sid);RETURN jsonb_build_object('token',tok);
 END IF;
 PERFORM auth_private.require_admin();
 IF p_operation='holiday' THEN IF p_data->>'operation' IS DISTINCT FROM 'generate' THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;RETURN finance.holiday_command(actor,p_data);
 ELSIF p_operation='block' THEN IF length(btrim(coalesce(reason,''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 IF p_data->>'id' IS NULL THEN INSERT INTO finance.transport_blocks(user_id,date_start,date_end,reason) VALUES((p_data->>'userId')::uuid,(p_data->>'from')::date,(p_data->>'to')::date,reason) RETURNING id INTO rid;
 ELSE UPDATE finance.transport_blocks SET active=false,version=version+1 WHERE id=(p_data->>'id')::uuid AND version=(p_data->>'version')::bigint AND active RETURNING id INTO rid;IF rid IS NULL THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;END IF;PERFORM app.activity_audit('transport-block',rid,reason,null,p_data);RETURN jsonb_build_object('id',rid);
 ELSIF p_operation='preview' THEN IF p_data->>'operation'='finalize' THEN m:=finance.month_start(p_data->>'period');PERFORM finance.guard_open(m);res:=finance.bundle(m,'realized');ELSIF p_data->>'operation'='holiday-waive' THEN m:=date_trunc('month',(p_data->>'date')::date)::date;PERFORM finance.guard_open(m);res:=finance.waive_impact(p_data);ELSIF p_data->>'operation'='holiday-cancel' THEN m:=date_trunc('month',(p_data->>'date')::date)::date;PERFORM finance.guard_open(m);SELECT jsonb_build_object('runId',r.id,'state',r.state,'count',(SELECT count(*) FROM finance.holiday_effects WHERE run_id=r.id),'jtm',(SELECT coalesce(sum(l.jtm),0)::text FROM finance.holiday_effects e JOIN finance.jtm_ledger l ON l.id=e.ledger_id WHERE e.run_id=r.id)) INTO res FROM finance.holiday_runs r WHERE r.id=(p_data->>'runId')::uuid AND r.date=(p_data->>'date')::date;IF res IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF; ELSIF p_data->>'operation'='correction' THEN m:=finance.month_start(p_data->>'targetPeriod');PERFORM finance.guard_open(m);res:=finance.correction_basis(p_data);ELSE RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 IF length(btrim(coalesce(reason,''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;
 INSERT INTO ops.finance_previews(actor_id,request,fingerprint,result) VALUES(actor,p_data,finance.digest(res::text),res) RETURNING * INTO v;RETURN jsonb_build_object('previewId',v.id,'result',res,'expiresAt',v.expires_at);
 ELSIF p_operation='commit' THEN
 SELECT * INTO v FROM ops.finance_previews WHERE id=(p_data->>'previewId')::uuid FOR UPDATE;IF v.id IS NULL OR v.actor_id<>actor OR v.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;IF v.consumed_at IS NOT NULL THEN RETURN v.result;END IF;d:=v.request;reason:=d->>'reason';
 IF d->>'operation'='finalize' THEN m:=finance.month_start(d->>'period');PERFORM finance.guard_open(m);res:=finance.bundle(m,'realized');IF finance.digest(res::text)<>v.fingerprint THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;IF jsonb_array_length(res->'issues')>0 THEN RAISE EXCEPTION 'FINANCE_BLOCKED' USING ERRCODE='42501';END IF;
 INSERT INTO finance.honor_periods(period_start) VALUES(m) ON CONFLICT DO NOTHING;SELECT id INTO pid FROM finance.honor_periods WHERE period_start=m FOR UPDATE;
 FOR s IN SELECT value FROM jsonb_array_elements(res->'statements') LOOP
 sid:=gen_random_uuid();s:=s||jsonb_build_object('statementId',sid,'trxId','SG-'||to_char(m,'YYYYMM')||'-'||replace(sid::text,'-',''),'finalizedAt',transaction_timestamp(),'mode','final');checksum:=finance.digest(s::text);
 INSERT INTO finance.honor_statements(id,period_id,user_id,trx_id,snapshot,total_jtm,total_honor,checksum) VALUES(sid,pid,(s->'recipient'->>'id')::uuid,s->>'trxId',s,(s->>'totalJtm')::numeric,(s->>'total')::numeric,checksum);
 FOR l IN SELECT value FROM jsonb_array_elements(s->'lines') LOOP INSERT INTO finance.honor_statement_lines(statement_id,component,source_ref,ledger_id,snapshot) VALUES(sid,l->>'component',(l->>'sourceRef')::uuid,(l->>'ledgerId')::uuid,l);END LOOP;
 INSERT INTO finance.notification_outbox(dedupe_key,recipient_id,statement_id,kind) VALUES('honor-final:'||sid,(s->'recipient'->>'id')::uuid,sid,'honor_final');END LOOP;
 UPDATE finance.period_guards SET finalized_at=transaction_timestamp() WHERE period_start=m;UPDATE finance.honor_periods SET state='final',finalized_at=transaction_timestamp(),finalized_by=actor WHERE id=pid;res:=jsonb_build_object('period',d->>'period','state','final','beneficiaries',res->'beneficiaries');rid:=pid;
 ELSIF d->>'operation'='holiday-waive' THEN res:=finance.waive_impact(d);IF finance.digest(res::text) IS DISTINCT FROM v.fingerprint THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;res:=finance.holiday_command(actor,(d-'operation')||jsonb_build_object('operation','waive'));rid:=actor; ELSIF d->>'operation'='holiday-cancel' THEN SELECT jsonb_build_object('runId',r.id,'state',r.state,'count',(SELECT count(*) FROM finance.holiday_effects WHERE run_id=r.id),'jtm',(SELECT coalesce(sum(l.jtm),0)::text FROM finance.holiday_effects e JOIN finance.jtm_ledger l ON l.id=e.ledger_id WHERE e.run_id=r.id)) INTO res FROM finance.holiday_runs r WHERE r.id=(d->>'runId')::uuid AND r.date=(d->>'date')::date;IF finance.digest(res::text) IS DISTINCT FROM v.fingerprint THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;res:=finance.holiday_command(actor,(d-'operation')||jsonb_build_object('operation','cancel'));rid:=(d->>'runId')::uuid; ELSE m:=finance.month_start(d->>'targetPeriod');PERFORM finance.guard_open(m);res:=finance.correction_basis(d);IF finance.digest(res::text)<>v.fingerprint THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;
 INSERT INTO finance.corrections(statement_id,target_period,sequence,baseline_total,corrected_total,delta,reason,evidence,revision,approved_by) VALUES((res->>'sourceStatementId')::uuid,m,(res->>'sequence')::int,(res->>'baseline')::numeric,(res->>'correctedTotal')::numeric,(res->>'delta')::numeric,reason,d->>'evidence',res->'revision',actor) RETURNING id INTO rid;
 INSERT INTO finance.notification_outbox(dedupe_key,recipient_id,statement_id,kind) VALUES('honor-correction:'||rid,(res->>'recipientId')::uuid,(res->>'sourceStatementId')::uuid,'honor_correction');res:=res||jsonb_build_object('id',rid);END IF;
 UPDATE ops.finance_previews SET consumed_at=clock_timestamp(),result=res WHERE id=v.id;PERFORM app.activity_audit('honor-'||(d->>'operation'),rid,reason,null,res);RETURN res;
 ELSE RAISE EXCEPTION 'FINANCE_INVALID' USING ERRCODE='22023';END IF;END $$;
CREATE FUNCTION app.finance_verify(p_token text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce((SELECT jsonb_build_object('status',CASE WHEN EXISTS(SELECT 1 FROM finance.corrections WHERE statement_id=s.id) THEN 'corrected' ELSE 'valid' END,'documentType','Slip honorarium','period',s.snapshot->>'period','school',s.snapshot->'school'->>'name','recipient',left(s.snapshot->'recipient'->>'name',1)||'***') FROM finance.document_tokens t JOIN finance.honor_statements s ON s.id=t.statement_id WHERE t.token_hash=finance.digest(p_token)),'{"status":"not_found"}'::jsonb) $$;
CREATE FUNCTION finance.immutable_final() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'FINAL_IMMUTABLE' USING ERRCODE='42501';END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['finance.honor_statements','finance.honor_statement_lines','finance.corrections','finance.holiday_effects'] LOOP EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION finance.immutable_final()',t);END LOOP;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA finance,app FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.finance_read(text,jsonb),app.finance_command(text,text,jsonb),app.finance_verify(text) TO sim_guru_business;
CREATE FUNCTION auth_private.consume_document_verify(p_key text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE n int;start_at timestamptz:=date_trunc('minute',clock_timestamp());BEGIN IF p_key!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_RATE_KEY';END IF;INSERT INTO auth_private.auth_rate_limits(scope,key_hash,window_start,count) VALUES('document_verify',p_key,start_at,1) ON CONFLICT(scope,key_hash,window_start) DO UPDATE SET count=least(auth_private.auth_rate_limits.count+1,31) RETURNING count INTO n;RETURN CASE WHEN n>30 THEN greatest(1,ceil(extract(epoch FROM start_at+interval '1 minute'-clock_timestamp()))::int) ELSE 0 END;END $$;
REVOKE ALL ON FUNCTION auth_private.consume_document_verify(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION auth_private.consume_document_verify(text) TO sim_guru_auth;
CREATE FUNCTION finance.period_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF OLD.state='final' THEN RAISE EXCEPTION 'FINAL_IMMUTABLE' USING ERRCODE='42501';END IF;RETURN NEW;END $$;
CREATE TRIGGER final_period_immutable BEFORE UPDATE OR DELETE ON finance.honor_periods FOR EACH ROW EXECUTE FUNCTION finance.period_immutable();
REVOKE ALL ON FUNCTION finance.period_immutable() FROM PUBLIC;
RESET ROLE;
